#include <Arduino.h>
#include <ESP_I2S.h>
#include <math.h>

// INMP441 -> ESP32-S3
// SD  -> GPIO 4 (I2S data in)
// WS  -> GPIO 5
// SCK -> GPIO 6
static constexpr int PIN_SD  = 4;
static constexpr int PIN_WS  = 5;
static constexpr int PIN_SCK = 6;

static constexpr uint32_t SAMPLE_RATE = 16000;
static constexpr int N = 256;                 // FFT size; frequency spacing = 62.5 Hz
static constexpr float PI_F = 3.14159265358979323846f;

I2SClass I2S;
int32_t raw[N];
float re[N], im[N];

void fft256() {
  // Bit-reversal permutation
  int j = 0;
  for (int i = 1; i < N; ++i) {
    int bit = N >> 1;
    while (j & bit) { j ^= bit; bit >>= 1; }
    j ^= bit;
    if (i < j) {
      float tr = re[i]; re[i] = re[j]; re[j] = tr;
      float ti = im[i]; im[i] = im[j]; im[j] = ti;
    }
  }

  for (int len = 2; len <= N; len <<= 1) {
    float angle = -2.0f * PI_F / len;
    float wlenR = cosf(angle), wlenI = sinf(angle);
    for (int i = 0; i < N; i += len) {
      float wr = 1.0f, wi = 0.0f;
      for (int k = 0; k < len / 2; ++k) {
        int u = i + k, v = u + len / 2;
        float vr = re[v] * wr - im[v] * wi;
        float vi = re[v] * wi + im[v] * wr;
        re[v] = re[u] - vr; im[v] = im[u] - vi;
        re[u] += vr; im[u] += vi;
        float nextWr = wr * wlenR - wi * wlenI;
        wi = wr * wlenI + wi * wlenR;
        wr = nextWr;
      }
    }
  }
}

void setup() {
  Serial.begin(115200);
  delay(1200);
  Serial.println("{\"status\":\"boot\",\"message\":\"Starting I2S\"}");

  // BCLK, WS, DOUT (unused), DIN
  I2S.setPins(PIN_SCK, PIN_WS, -1, PIN_SD);

  bool ok = I2S.begin(
    I2S_MODE_STD,
    SAMPLE_RATE,
    I2S_DATA_BIT_WIDTH_32BIT,
    I2S_SLOT_MODE_MONO,
    I2S_STD_SLOT_LEFT
  );

  if (!ok) {
    Serial.println("{\"status\":\"error\",\"message\":\"I2S begin failed\"}");
    while (true) delay(1000);
  }
  Serial.println("{\"status\":\"ready\",\"sampleRate\":16000,\"fftSize\":256}");
}

void loop() {
  size_t got = I2S.readBytes((char*)raw, sizeof(raw));
  int count = got / sizeof(int32_t);
  if (count != N) return;

  double sumSq = 0.0;
  int32_t peakAbs = 0;

  for (int i = 0; i < N; ++i) {
    // INMP441 24-bit samples are left-aligned in the 32-bit I2S word.
    int32_t s = raw[i] >> 8;
    int32_t a = (s == INT32_MIN) ? INT32_MAX : abs(s);
    if (a > peakAbs) peakAbs = a;
    sumSq += (double)s * (double)s;

    // Hann window
    float window = 0.5f - 0.5f * cosf(2.0f * PI_F * i / (N - 1));
    re[i] = (float)s * window;
    im[i] = 0.0f;
  }

  float rms = sqrtf((float)(sumSq / N));
  fft256();

  // 5 broad logarithmic-ish bands spanning the useful range up to Nyquist.
  // Bin width = 16000/256 = 62.5 Hz. Ignore DC bin 0.
  const int edges[6] = {1, 4, 8, 16, 32, 129};
  float bands[5] = {0, 0, 0, 0, 0};
  float maxMag = 0;
  int peakBin = 0;

  for (int b = 0; b < 5; ++b) {
    double energy = 0;
    for (int k = edges[b]; k < edges[b + 1]; ++k) {
      float mag = sqrtf(re[k] * re[k] + im[k] * im[k]);
      energy += (double)mag * mag;
      if (mag > maxMag) { maxMag = mag; peakBin = k; }
    }
    bands[b] = sqrtf((float)(energy / (edges[b + 1] - edges[b])));
  }

  float peakHz = peakBin * (float)SAMPLE_RATE / N;

  // One JSON line per frame for the browser dashboard.
  Serial.print("{\"status\":\"data\",\"rms\":");
  Serial.print(rms, 0);
  Serial.print(",\"peakHz\":");
  Serial.print(peakHz, 1);
  Serial.print(",\"peakRaw\":");
  Serial.print(peakAbs);
  Serial.print(",\"bands\":[");
  for (int b = 0; b < 5; ++b) {
    if (b) Serial.print(",");
    Serial.print(bands[b], 1);
  }
  Serial.println("]}");
}
